/**
 *
 * MenuSubmenu is a submenu component for nested menu structures.
 *
 * [Live Demo](https://www.primereact.org/menu/)
 *
 * @module MenuSubmenu
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { UseMenuSubmenuExposes, UseMenuSubmenuOpenChangeEvent, UseMenuSubmenuProps, UseMenuSubmenuState } from '@primereact/types/headless/menu';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { MenuRootInstance } from './MenuRoot.types';
/**
 * Defines passthrough(pt) options type in MenuSubmenu component.
 */
export type MenuSubmenuPassThroughType<E> = PassThroughType<MenuSubmenuInstance, E>;
/**
 * Defines passthrough(pt) options of MenuSubmenu component.
 */
export interface MenuSubmenuPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: MenuSubmenuPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Event fired when the menu's open state changes.
 * @extends UseMenuOpenChangeEvent
 */
export interface MenuSubmenuOpenChangeEvent extends UseMenuSubmenuOpenChangeEvent {
}
/**
 * Defines valid properties in MenuSubmenu component.
 */
export interface MenuSubmenuProps extends BaseComponentProps<MenuSubmenuInstance, Omit<UseMenuSubmenuProps, 'onOpenChange'>, MenuSubmenuPassThrough> {
    /**
     * Callback fired when the submenu's open state changes.
     * @param event.value The new value of the menu's open state.
     * @returns void
     */
    onOpenChange?: (event: MenuSubmenuOpenChangeEvent) => void;
}
/**
 * Defines valid state in MenuSubmenu component.
 * @extends UseMenuSubmenuState
 */
export interface MenuSubmenuState extends UseMenuSubmenuState {
}
/**
 * Defines the methods and properties exposed by MenuSubmenu component.
 * @extends UseMenuSubmenuExposes
 */
export interface MenuSubmenuExposes extends UseMenuSubmenuExposes {
    /**
     * The Menu component instance.
     */
    menu: MenuRootInstance | undefined | null;
}
/**
 * Instance of MenuSubmenu component.
 */
export type MenuSubmenuInstance = ComponentInstance<MenuSubmenuProps, MenuSubmenuState, MenuSubmenuExposes>;
